package i18n

var boot_config_huaweiEN = map[string]string{
	"help.boot_config.apply.huawei.object":                       bootConfigApplyHuaweiObjectEN,
	"cmd.boot_config_top.fetch_oss_resources.huawei.usage_notes": "Use this command to query the validated Huawei Cloud object-storage boot-config resources.\n\nParameter source:\n  --cloud-account-id string\n    Comes from `cloud-account list --storage-type object` or `cloud-account detail --id <account_id>`.\n\nReal execution order:\n  1. Resolve the existing target account first.\n  2. Query `regions,zones` and confirm the account-scoped region and zone candidates.\n  3. Query `flavors,os_types` with the selected `--zone-id`; add `--flavor-vcpus` and `--flavor-ram` only when you want the CLI to filter the displayed flavor rows.\n  4. Query `system_volume_types,volume_types` with the selected `--zone-id`.\n  5. Query `networks` first, then query `subnets,security_groups` after you have confirmed the target VPC; if the backend already returns everything together, you can also request `networks,subnets,security_groups` in one call.\n  6. Continue IP and bandwidth details with `hyperbdrctl boot-config-wizard subnet-config` after `network_id` and `subnet_id` are known.\n\nRun the minimum account-scoped region and zone query like this:\n  hyperbdrctl boot-config fetch-oss-resources huawei \\\n    --cloud-account-id <account_id> \\\n    --fetch-res regions,zones \\\n    --output json\n\nThen query flavors and OS types:\n  hyperbdrctl boot-config fetch-oss-resources huawei \\\n    --cloud-account-id <account_id> \\\n    --fetch-res flavors,os_types \\\n    --zone-id <zone_id> \\\n    --flavor-vcpus 2 \\\n    --flavor-ram 4 \\\n    --output json\n\nThen query volume types:\n  hyperbdrctl boot-config fetch-oss-resources huawei \\\n    --cloud-account-id <account_id> \\\n    --fetch-res system_volume_types,volume_types \\\n    --zone-id <zone_id> \\\n    --output json\n\nThen query networks, subnets, and security groups:\n  hyperbdrctl boot-config fetch-oss-resources huawei \\\n    --cloud-account-id <account_id> \\\n    --fetch-res networks,subnets,security_groups \\\n    --output json\n\nDo not treat this command as a replacement for `boot-config-wizard subnet-config`; keep subnet-scoped IP and bandwidth discovery there.\n\nFor scripting against the raw API fields, add:\n  --output json",
}
